import json

import six
from typing import Union, Optional, List, ClassVar, Dict

from taf.cloud.cbam.vnf.vnf import VNF
from taf.cloud.cbam.schemas.v4.vnf_instance import VnfInfo
from taf.cloud.cbam.schemas.v4.no_data import NoData
from taf.cloud.cbam.schemas.v4.vnf_lcm_op_occ import VnfLcmOpOcc
from taf.cloud.cbam.schemas.problem_details import ProblemDetails
from taf.cloud.cbam import exception


class SupportedVnf4Schemas(object):
    ProblemDetails = ProblemDetails  # type: ClassVar
    VnfInfo = VnfInfo  # type: ClassVar
    NoData = NoData  # type: ClassVar
    OperationExecution = VnfLcmOpOcc  # type: ClassVar
    VnfLcmOpOcc = VnfLcmOpOcc  # type: ClassVar


class VNF4(VNF):
    supported_schemas = SupportedVnf4Schemas()

    def __init__(self, session, api_version='4.0'):
        self.session = session
        self.api_version = api_version

    def _to_endpoint(self, method, url, api_version='4.0', **content):
        response = self.session.send_request(method=method,
                                             endpoint=url,
                                             api_version=api_version,
                                             **content)
        return response

    def create(self, vnf_info):
        # type: (SupportedVnf4Schemas.VnfInfo) ->Union[SupportedVnf4Schemas.VnfInfo,SupportedVnf4Schemas.ProblemDetails]
        body = {'vnfdId': vnf_info.vnfd_id,
                'vnfInstanceName': vnf_info.name,
                'vnfInstanceDescription': vnf_info.description
                }
        response = self._to_endpoint(method='post',
                                     url='vnflcm/v1/vnf_instances',
                                     data=json.dumps(body))
        response = response.convert(success_class=self.supported_schemas.VnfInfo,
                                    fail_class=self.supported_schemas.ProblemDetails,
                                    success_codes=[201])
        return response

    def instantiate(self,
                    name,
                    body_content,
                    password,
                    flavour_id=None):
        vnf_id = self._get_vnf_id_by_name(name)
        body = self._create_instantiate_request_body(body_content, password,
                                                     flavour_id)
        endpoint = 'vnflcm/v1/vnf_instances/{}/instantiate'.format(vnf_id)
        response = self._to_endpoint(
            method='post', url=endpoint,
            data=body, api_version=self.api_version)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.NoData,
            success_codes=[202])

        return response

    @staticmethod
    def _create_instantiate_request_body(body,
                                         password,
                                         flavour_id=None):
        # type: (Dict, str, Optional[str]) -> str

        if flavour_id is not None:
            body['flavourId'] = flavour_id
        if 'apiVersion' in body:
            del body['apiVersion']

        body['vimConnectionInfo'][0]['accessInfo']['password'] = password
        return json.dumps(body)

    def delete_vnf(self, vnf_info):
        # type: (SupportedVnf4Schemas.VnfInfo) -> Optional[SupportedVnf4Schemas.ProblemDetails]
        vnf_id = self._get_vnf_id_by_name(vnf_info.name)
        endpoint = 'vnflcm/v1/vnf_instances/{}'.format(vnf_id)

        response = self._to_endpoint(method='delete',
                                     url=endpoint)
        if response.status_code != 204:
            return self.supported_schemas.ProblemDetails.from_response_dict(response.data)
        return None

    def terminate(self,
                  name,
                  termination_type='GRACEFUL',
                  termination_timeout=None):
        vnf_id = self._get_vnf_id_by_name(name)
        body = self._create_terminate_request_body(
            termination_type, termination_timeout)
        endpoint = 'vnflcm/v1/vnf_instances/{}/terminate'.format(vnf_id)

        response = self._to_endpoint(method='post',
                                     url=endpoint,
                                     data=json.dumps(body))
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.NoData,
            success_codes=[202])
        return response

    @staticmethod
    def _create_terminate_request_body(termination_type,
                                       termination_timeout):
        body = {'terminationType': termination_type}
        if termination_timeout is not None:
            body.update(
                {'gracefulTerminationTimeout': termination_timeout})
        return body

    def modify(self, name, parameters_to_change):
        vnf_id = self._get_vnf_id_by_name(name)
        endpoint = 'vnflcm/v1/vnf_instances/{}'.format(vnf_id)

        response = self._to_endpoint(method='patch',
                                     url=endpoint,
                                     data=parameters_to_change)

        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.NoData,
            success_codes=[202])

        return response

    def _get_vnf_id_by_name(self, name):
        vnfs_info = self.query_all_vnfs()

        if isinstance(vnfs_info, self.supported_schemas.ProblemDetails):
            problem_details = vnfs_info
            detail = problem_details.detail
            status = problem_details.status
            problem_message = 'Details: {}\nStatus: {}'.format(detail, status)

            exc_msg = "An error occured while querying VNFs: {}"
            exc_msg = exc_msg.format(problem_message)

            raise exception.VnfNameNotFoundException(exc_msg)

        for vnf in vnfs_info:
            if vnf.name == name:
                return vnf.id

        raise exception.VnfNameNotFoundException(name)

    def query_all_vnfs(self):
        # type: () -> Union[List[SupportedVnf4Schemas.VnfInfo], SupportedVnf4Schemas.ProblemDetails]
        response = self._to_endpoint(
            method='get', url='vnflcm/v1/vnf_instances')
        result = response.convert_list(
            success_codes=[200],
            success_class=self.supported_schemas.VnfInfo,
            fail_class=self.supported_schemas.ProblemDetails)

        return result

    def query_one(self, vnf_info):
        # type: (SupportedVnf4Schemas.VnfInfo) -> Union[SupportedVnf4Schemas.VnfInfo, SupportedVnf4Schemas.ProblemDetails]
        endpoint = 'vnflcm/v1/vnf_instances/{_id}'.format(_id=vnf_info.id)
        response = self._to_endpoint(
            method='get',
            url=endpoint)

        result = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.VnfInfo,
            success_codes=[200])

        return result

    def get_operation_execution_info(self, vnf_lcm_op_occ):
        # type: (VnfLcmOpOcc) -> VnfLcmOpOcc
        endpoint = 'vnflcm/v1/vnf_lcm_op_occs/{vnf_lcm_op_occ_id}'.format(
            vnf_lcm_op_occ_id=vnf_lcm_op_occ.operation_id)
        response = self._to_endpoint(method='get', url=endpoint)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.VnfLcmOpOcc,
            success_codes=[200]
        )
        return response

    def get_all_operation_execution_info(self, vnf_instance_name, all_fields):
        endpoint = 'vnflcm/v1/vnf_lcm_op_occs'
        body = self._create_get_all_operations_execution_info_body(vnf_instance_name, all_fields)
        response = self._to_endpoint(method='get', url=endpoint, params=body)
        response = response.convert_list(
            success_codes=[200],
            success_class=self.supported_schemas.VnfLcmOpOcc,
            fail_class=self.supported_schemas.ProblemDetails)

        return response

    def _create_get_all_operations_execution_info_body(self, vnf_instance_name, all_fields):
        body = {}
        if vnf_instance_name:
            body['vnfInstanceId'] = self._get_vnf_id_by_name(vnf_instance_name)
        if all_fields:
            body['all_fields'] = all_fields

        return body

    def get_vim_info(self, vnf_info, vim_info):
        raise NotImplementedError

    def _return_file_content(self, path_to_file):
        with open(path_to_file, 'r+') as fp:
            file_content = fp.read()
        return file_content

    def _return_content_for_given_type(self, params):
        if isinstance(params, six.string_types):
            content = self._return_file_content(params)
        elif isinstance(params, dict):
            parameters = {'additionalParams': params}
            content = json.dumps(parameters)
        else:
            content = None
        return content

    def post_custom_operation(self, vnf_info, custom_operation_name, additional_params=None):
        # type: (SupportedVnf4Schemas.VnfInfo, str, Optional[Union[str, dict]]) -> Union[SupportedVnf4Schemas.NoData, SupportedVnf4Schemas.ProblemDetails]

        content = self._return_content_for_given_type(additional_params)
        vnf_instance_id = self._get_vnf_id_by_name(vnf_info.name)
        endpoint = 'vnflcm/v1/vnf_instances/{vnfInstanceId}/custom/{customOperationName}'.format(
            vnfInstanceId=vnf_instance_id, customOperationName=custom_operation_name)

        if content:
            response = self._to_endpoint(method='post', url=endpoint, data=content)
        else:
            response = self._to_endpoint(method='post', url=endpoint)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.NoData,
            success_codes=[202])

        return response

    def put_vim_info(self,
                     vnf_instance_name,
                     vim_id,
                     interface_info,
                     vim_info_type,
                     **kwargs):
        raise NotImplementedError

    def upgrade(self, name, vnfd_id):
        vnf_id = self._get_vnf_id_by_name(name)
        endpoint = 'vnflcm/v1/vnf_instances/{vnfInstanceId}/upgrade'.format(vnfInstanceId=vnf_id)
        body = {'vnfdId': vnfd_id}

        response = self._to_endpoint(
            method='post',
            url=endpoint,
            data=json.dumps(body))
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.NoData,
            success_codes=[202])
        return response
